// Non-driving confidence checker for the unmodified Adams Bridge v2.0.3
// power2round_tb. Compile this as a second top beside power2round_tb.
module power2round_observer;
  integer writes = 0;
  integer checked = 0;

  always @(posedge power2round_tb.clk_tb) begin
    if (power2round_tb.reset_n_tb && power2round_tb.pk_t1_wren_tb) begin
      if (power2round_tb.pk_t1_wr_addr_tb !== writes[7:0])
        $fatal(1, "OBSERVER pk address: expected %0d got %0h", writes,
               power2round_tb.pk_t1_wr_addr_tb);
      for (integer lane = 0; lane < 8; lane = lane + 1) begin
        if (power2round_tb.pk_t1_wrdata_tb[lane] !==
            power2round_tb.coeff_high[8*writes+lane])
          $fatal(1, "OBSERVER pk data: write %0d lane %0d expected %0h got %0h",
                 writes, lane, power2round_tb.coeff_high[8*writes+lane],
                 power2round_tb.pk_t1_wrdata_tb[lane]);
        checked = checked + 1;
      end
      writes = writes + 1;
    end
  end

  initial begin
    wait (power2round_tb.done_tb === 1'b1);
    @(posedge power2round_tb.clk_tb);
    if (writes != 256)
      $fatal(1, "OBSERVER incomplete pk writes: expected 256 got %0d", writes);
    if (checked != 2048)
      $fatal(1, "OBSERVER incomplete pk comparisons: expected 2048 got %0d", checked);
    if (power2round_tb.tc_ctr !== 32'd2048)
      $fatal(1, "OBSERVER tb count: expected 2048 got %0h", power2round_tb.tc_ctr);
    if (power2round_tb.error_ctr !== 32'd0)
      $fatal(1, "OBSERVER tb errors: expected 0 got %0h", power2round_tb.error_ctr);
    if (power2round_tb.skmem_data !== power2round_tb.coeff_low)
      $fatal(1, "OBSERVER secret-key memory mismatch or unknown bit");
    $display("OBSERVER PASSED: 256 writes, 2048 case-exact pk comparisons, case-exact skmem");
  end
endmodule
